/**
 * The support domain: tickets, the messages in them and the people behind them.
 * Nothing here knows about a database, a framework or a provider.
 */

export type TicketStatus = "open" | "waiting" | "solved" | "spam";

/** inbound: from the customer. outbound: to the customer. note: internal, never sent. */
export type MessageKind = "inbound" | "outbound" | "note";

export type DeliveryStatus = "queued" | "sent" | "delivered" | "read" | "failed";

/** How a person is reached on a channel: an email address, an E.164 phone number, … */
export type IdentityKind = "email" | "phone" | "whatsapp" | "telegram" | (string & {});

export type Identity = { kind: IdentityKind; value: string };

export type Address = { address: string; name?: string | null };

export type Contact = {
  id: string;
  name: string | null;
  /** The product's customer (an organization, an account, …) this person belongs to. */
  customerId: string | null;
  /** The product's user id, when the person has an account. */
  userId: string | null;
  locale: string | null;
  blockedAt: Date | null;
  identities: Identity[];
};

export type Ticket = {
  id: string;
  /** A short number for agents to refer to a ticket. Never shown to customers. */
  number: number;
  channelId: string;
  subject: string | null;
  status: TicketStatus;
  contactId: string;
  customerId: string | null;
  assigneeId: string | null;
  /** Random token carried in reply addresses, so a reply finds its ticket even without headers. */
  replyToken: string;
  providerThreadId: string | null;
  /** When the customer's oldest unanswered message arrived; null when nobody is waiting on us. */
  waitingSince: Date | null;
  lastMessageAt: Date;
  lastInboundAt: Date | null;
  lastOutboundAt: Date | null;
  solvedAt: Date | null;
  /** The latest public message, shortened, for lists. */
  preview: string | null;
  previewKind: "inbound" | "outbound" | null;
  previewAuthorId: string | null;
  createdAt: Date;
  updatedAt: Date;
};

export type Attachment = {
  id: string;
  messageId: string | null;
  filename: string;
  contentType: string;
  size: number;
  storageKey: string;
  /** For inline images referenced as cid: in HTML. */
  contentId: string | null;
  inline: boolean;
};

export type Message = {
  id: string;
  ticketId: string;
  kind: MessageKind;
  channelId: string | null;
  /** The agent for outbound messages and notes; the customer's user id for messages written in a portal. */
  authorId: string | null;
  from: Address | null;
  to: Address[];
  cc: Address[];
  subject: string | null;
  /** What the person actually wrote this time: quoted history and signatures removed. */
  text: string;
  /** The whole plain-text body, quotes included. */
  fullText: string | null;
  /** The original HTML, sanitized. */
  html: string | null;
  rfcMessageId: string | null;
  inReplyTo: string | null;
  references: string[];
  providerMessageId: string | null;
  deliveryStatus: DeliveryStatus | null;
  deliveryError: string | null;
  /** Sent or received automatically: acknowledgements, out-of-office replies. */
  auto: boolean;
  source: "channel" | "portal" | "agent" | "api";
  createdAt: Date;
  attachments: Attachment[];
};

export type TicketEventType =
  | "created"
  | "assigned"
  | "status_changed"
  | "customer_linked"
  | "reopened"
  | "follow_up"
  | "contact_changed"
  | "forwarded"
  /** An agent corrected the topic or urgency Copilot gave the ticket. */
  | "insight_changed"
  /** An agent ran an action, or approved one Copilot proposed. For agents only: customers never see events. */
  | "action_run"
  /** Autopilot sent a reply with nobody reading it first. For agents only. */
  | "autopilot_sent"
  /** An agent marked a reply Autopilot sent as wrong. */
  | "autopilot_flagged";

export type TicketEvent = {
  id: string;
  ticketId: string;
  type: TicketEventType;
  actorId: string | null;
  data: Record<string, unknown>;
  createdAt: Date;
};

export type Agent = { id: string; name: string; email?: string | null };

export type CustomerSummary = { id: string; name: string };

/** One line about a customer's account, from `directory.describeCustomer`. */
export type AccountFact = { label: string; value: string; url?: string | null };

export type Urgency = "urgent" | "high" | "normal" | "low";
export type Mood = "calm" | "confused" | "frustrated" | "angry";

/** What Copilot understood of a ticket from the customer's latest message. */
export type TicketInsight = {
  ticketId: string;
  basedOnMessageId: string | null;
  /** One of the topics in the AI settings, or "other". */
  topic: string | null;
  urgency: Urgency | null;
  urgencyReason: string | null;
  mood: Mood | null;
  /** BCP-47, such as "en" or "pt-BR": the language the customer writes in. */
  language: string | null;
  /** One line, in the agents' language. */
  summary: string | null;
  /** Set when an agent changed the topic or urgency; Copilot doesn't overwrite them. */
  topicSetBy: string | null;
  urgencySetBy: string | null;
  updatedAt: Date;
};

export type SuggestionSource = {
  type: "knowledge" | "answer" | "fact" | "guidance" | "action";
  id: string;
  title: string;
  url?: string | null;
  /** For "action": what the lookup found, in one line. */
  detail?: string | null;
};

export type SuggestionStatus = "pending" | "used" | "edited" | "discarded" | "stale";

/** A reply Copilot drafted, or why it couldn't. */
export type Suggestion = {
  id: string;
  ticketId: string;
  basedOnMessageId: string;
  kind: "draft" | "cannot_answer";
  text: string | null;
  reason: string | null;
  sources: SuggestionSource[];
  /** Changes the draft assumes: each waits for an agent to approve or skip it. */
  actions: ProposedAction[];
  status: SuggestionStatus;
  /** The ticket's topic and the customer's language when it was drafted: what its outcome counts towards. */
  topic: string | null;
  language: string | null;
  /** Set when the topic is on Autopilot: where this reply stands. Null for an ordinary suggestion. */
  autopilot: AutopilotState | null;
  /** When a held reply is sent unless someone steps in. */
  sendAt: Date | null;
  /** Why Autopilot left this reply to a person, when the topic is on. */
  autopilotBlock: AutopilotBlock | null;
  createdAt: Date;
};

/** "hold": queued, then sent after a delay unless someone steps in. "immediate": sent as soon as it's drafted. */
export type AutopilotMode = "hold" | "immediate";

/**
 * held: waiting out the delay. sending: being sent. sent: went out. cancelled: someone stepped in,
 * or it no longer applied when its time came. failed: the channel didn't take it.
 */
export type AutopilotState = "held" | "sending" | "sent" | "cancelled" | "failed";

/** Why a reply on an Autopilot topic went to a person instead. */
export type AutopilotBlock =
  | "stopped"
  | "unknown_customer"
  | "channel"
  | "asked_for_human"
  | "not_helped"
  | "mood"
  | "urgency"
  | "long_thread"
  | "needs_approval"
  | "not_confident"
  | "unsourced"
  | "language"
  | "hourly_cap"
  /** An agent stopped a held reply. */
  | "held_back"
  /** By the time a held reply was due, the ticket had moved on: a note, a status change, a paused topic. */
  | "moved_on"
  | "send_failed";

/** "always": an agent approves every run. "never": a read-only lookup Copilot may run while drafting. */
export type ActionApproval = "always" | "never";

/** One input of an action, as a form field. Built from the action's schema. */
export type ActionField = {
  name: string;
  label: string;
  description: string | null;
  /** "json" is the fallback for shapes a small form can't show: lists and nested objects. */
  kind: "text" | "number" | "boolean" | "select" | "date" | "json";
  required: boolean;
  options?: string[];
};

/** An action an agent can run on a ticket. */
export type TicketAction = { name: string; title: string; description: string; approval: ActionApproval; fields: ActionField[] };

/** A declared action, for the settings screen. `enabled` only varies for "never" actions: the team can stop Copilot running them on its own. */
export type ActionSetting = { name: string; title: string; description: string; approval: ActionApproval; enabled: boolean };

/**
 * succeeded and failed are what your `run` answered (`ok`). timed_out and errored mean it didn't
 * answer: the change may or may not have happened.
 */
export type ActionRunStatus = "running" | "succeeded" | "failed" | "timed_out" | "errored";

/** One run of an action: the log entry. */
export type ActionRun = {
  id: string;
  ticketId: string;
  /** The suggestion that proposed it, or whose draft looked it up. */
  suggestionId: string | null;
  action: string;
  title: string;
  input: Record<string, unknown>;
  /** "draft": a lookup Copilot ran while drafting. "suggestion": a proposal an agent approved. "manual": run from the ticket's menu. */
  trigger: "draft" | "suggestion" | "manual";
  status: ActionRunStatus;
  /** What your `run` said happened. */
  summary: string | null;
  data: Record<string, unknown> | null;
  /** The agent who approved or ran it. Null for lookups Copilot ran. */
  approvedBy: string | null;
  durationMs: number | null;
  createdAt: Date;
  finishedAt: Date | null;
};

/** An action Copilot proposes with a draft, as stored. */
export type ProposedAction = {
  name: string;
  title: string;
  input: Record<string, unknown>;
  /** Why the conversation calls for it, for the agent. */
  reason: string;
  /** An agent skipped it. */
  declined: boolean;
};

/** A proposed action with what an agent needs to decide on it. */
export type ProposedActionView = ProposedAction & {
  state: "proposed" | "running" | "done" | "failed" | "declined";
  fields: ActionField[];
  /** Its latest run, once approved. */
  run: ActionRun | null;
};

export type SuggestionView = Omit<Suggestion, "actions"> & { actions: ProposedActionView[] };

/**
 * An answer the team wrote once and approved for reuse. Drafts treat it as their most trusted
 * source, and agents insert it into the reply box as it is.
 */
export type ApprovedAnswer = {
  id: string;
  /** The question it answers, or a short title. */
  title: string;
  /** May hold the placeholders {name}, {company} and {agent}, filled in when it's used. */
  text: string;
  /** BCP-47. Set: only for customers writing in this language. Null: for everyone. */
  language: string | null;
  /** The ticket it was saved from, when there was one. */
  ticketId: string | null;
  createdBy: string | null;
  createdAt: Date;
  updatedAt: Date;
};

/** A rule the team's own edits suggest adding to the guidance. Nothing changes until someone accepts it. */
export type GuidanceSuggestion = {
  id: string;
  /** The line to add to the guidance. */
  rule: string;
  /** What agents kept doing that suggests it. */
  reason: string;
  /** Tickets where they did it. */
  ticketIds: string[];
  status: "pending" | "accepted" | "dismissed";
  createdAt: Date;
};

/** A question the knowledge didn't answer, or one whose draft agents threw away. */
export type Gap = {
  id: string;
  theme: string;
  status: "open" | "resolved" | "dismissed";
  /** Tickets that asked it. */
  count: number;
  lastSeenAt: Date | null;
  /** The latest few. */
  tickets: { id: string; number: number; subject: string | null }[];
  createdAt: Date;
};

import type { Address, DeliveryStatus, IdentityKind } from "./types";

/**
 * A channel adapter connects one provider account (a Resend domain, a Microsoft 365 mailbox,
 * a Twilio number, a WhatsApp business number, …) to the inbox. Adapters only translate:
 * provider payloads in, provider API calls out. Threading, storage and rules live in the service.
 */
export interface Channel {
  /** Stable id from your config, stored on every ticket. Never change it once tickets exist. */
  id: string;
  kind: "email" | "sms" | "whatsapp" | "telegram" | "api";
  /** How senders on this channel are identified. */
  identityKind: IdentityKind;
  /** What customers write to, for display: "support@acme.com", "+1 415 555 0133". */
  address: string;
  capabilities: ChannelCapabilities;
  /**
   * Email only: an address on a receiving domain that routes back to this channel, such as
   * "support@in.acme.com". Replies carry a ticket token in it ("support+t-<token>@in.acme.com"),
   * which threads them even when the customer's mail client drops the headers.
   */
  replyAddress?: string;

  /**
   * Verifies and parses a provider webhook. Return `response` when the provider expects a
   * specific reply (a verification challenge, empty TwiML); otherwise the handler answers 200.
   * Throw `WebhookError` for requests that fail verification.
   */
  webhook?(request: Request): Promise<WebhookResult>;

  /**
   * For providers that are polled or need subscriptions renewed. Called on a schedule with the
   * state the previous call returned (null the first time). Must be safe to run concurrently
   * with itself returning the same events: ingestion is idempotent.
   */
  sync?(state: ChannelState | null): Promise<{ events: ChannelEvent[]; state: ChannelState }>;

  send(message: OutboundMessage): Promise<SendResult>;
}

export type ChannelCapabilities = {
  subject: boolean;
  attachments: { maxBytes: number; maxCount: number } | false;
  /** Longest message the provider accepts, in characters; null when effectively unlimited. */
  maxTextLength: number | null;
  /**
   * thread: each subject is its own conversation (email).
   * contact: one running conversation per person (SMS, WhatsApp, Telegram).
   */
  conversation: "thread" | "contact";
  /** Hours after the customer's last message during which free-form replies are allowed. */
  replyWindowHours: number | null;
  deliveryReceipts: boolean;
};

export type ChannelState = Record<string, unknown>;

export type WebhookResult = { events: ChannelEvent[]; response?: Response };

export type ChannelEvent =
  | { type: "message"; message: InboundMessage }
  | {
      type: "status";
      providerMessageId: string;
      status: DeliveryStatus;
      error?: string | null;
      /** The RFC Message-ID the provider assigned, when it reports it with the status. */
      rfcMessageId?: string | null;
      at: Date;
    };

export type InboundAttachment = {
  filename: string;
  contentType: string;
  size: number | null;
  contentId?: string | null;
  inline?: boolean;
  /** Downloads the bytes. Called once, after the message is accepted. */
  read(): Promise<Uint8Array>;
};

export type InboundMessage = {
  /** Unique per channel; used to drop duplicates. */
  providerMessageId: string;
  /**
   * Mailbox-backed channels (Microsoft 365, Gmail) also see mail your team sent from the mailbox
   * itself. Those arrive as "outbound" so they appear in the ticket as replies.
   */
  direction?: "inbound" | "outbound";
  from: Address;
  to: Address[];
  cc?: Address[];
  subject?: string | null;
  text?: string | null;
  html?: string | null;
  /** Lower-cased header names. Only what the core needs: auto-reply and bounce detection. */
  headers?: Record<string, string>;
  rfcMessageId?: string | null;
  inReplyTo?: string | null;
  references?: string[];
  providerThreadId?: string | null;
  receivedAt: Date;
  attachments?: InboundAttachment[];
  /**
   * "api" for messages your app creates itself (a contact form). They become tickets like any
   * other, but never get the automatic acknowledgement: your form already confirms.
   */
  source?: "channel" | "api";
};

export type OutboundAttachment = { filename: string; contentType: string; content: Uint8Array };

export type OutboundMessage = {
  /** Our message id. Adapters pass it as an idempotency key where the provider supports one. */
  id: string;
  to: Address[];
  cc?: Address[];
  /** Display name to send as; the adapter's configured address is used. */
  fromName?: string | null;
  replyTo?: Address | null;
  subject?: string | null;
  text: string;
  html?: string | null;
  attachments?: OutboundAttachment[];
  /** The Message-ID to use, when the adapter lets us choose it. Includes angle brackets. */
  rfcMessageId?: string | null;
  inReplyTo?: string | null;
  references?: string[];
  providerThreadId?: string | null;
  /** The provider message this replies to, for channels that quote (WhatsApp context). */
  replyToProviderMessageId?: string | null;
  headers?: Record<string, string>;
};

export type SendResult = {
  providerMessageId: string;
  /** The RFC Message-ID the provider actually used, when it reports one. */
  rfcMessageId?: string | null;
  providerThreadId?: string | null;
  status?: DeliveryStatus;
};

/** A webhook that failed verification. The handler answers with `status` and logs nothing sensitive. */
export class WebhookError extends Error {
  constructor(
    message: string,
    readonly status = 401
  ) {
    super(message);
    this.name = "WebhookError";
  }
}

/** A provider call that failed. `retryable` tells the caller whether trying again can help. */
export class ChannelError extends Error {
  constructor(
    message: string,
    readonly retryable: boolean,
    readonly status?: number
  ) {
    super(message);
    this.name = "ChannelError";
  }
}

import type {
  Attachment,
  Contact,
  DeliveryStatus,
  Identity,
  Message,
  Ticket,
  TicketEvent,
  TicketStatus,
} from "./types";
import type { ChannelState } from "./channel";
import type { PeriodBreakdown, PeriodTotals, StatsRange } from "./insights";

/**
 * Everything the service needs from a database. `postgres/store.ts` implements it with Drizzle;
 * port that file (and `postgres/schema.ts`) to use another database.
 */
export interface SupportStore {
  /** Runs `fn` atomically where the database supports it. */
  transaction<T>(fn: (store: SupportStore) => Promise<T>): Promise<T>;

  findContactByIdentity(identity: Identity): Promise<Contact | null>;
  getContact(id: string): Promise<Contact | null>;
  getContacts(ids: string[]): Promise<Contact[]>;
  createContact(input: NewContact): Promise<Contact>;
  updateContact(id: string, patch: Partial<Pick<Contact, "name" | "customerId" | "userId" | "locale" | "blockedAt">>): Promise<void>;
  /** Ignored when the identity already belongs to someone. */
  addIdentity(contactId: string, identity: Identity): Promise<void>;

  getTicket(id: string): Promise<Ticket | null>;
  findTicketByToken(token: string): Promise<Ticket | null>;
  /** The ticket holding a message with any of these RFC Message-IDs, newest first. */
  findTicketByRfcMessageIds(ids: string[]): Promise<Ticket | null>;
  findTicketByProviderThread(channelId: string, providerThreadId: string): Promise<Ticket | null>;
  /** The contact's most recently active ticket on a channel, any status. */
  findLatestTicket(channelId: string, contactId: string): Promise<Ticket | null>;
  createTicket(input: NewTicket): Promise<Ticket>;
  /** Gives the contact's tickets that have no customer yet this customer. */
  linkContactTickets(contactId: string, customerId: string): Promise<void>;
  updateTicket(id: string, patch: TicketPatch): Promise<Ticket>;
  listTickets(query: TicketQuery): Promise<{ items: Ticket[]; total: number }>;
  countTickets(query: { assigneeId?: string | null }): Promise<TicketCounts>;

  /** Inserts a message; returns null if one with the same channel and provider id exists. */
  insertMessage(input: NewMessage): Promise<Message | null>;
  updateMessage(id: string, patch: MessagePatch): Promise<void>;
  getMessage(id: string): Promise<Message | null>;
  findMessageByProviderId(channelId: string, providerMessageId: string): Promise<Message | null>;
  listMessages(ticketId: string, options: { includeNotes: boolean }): Promise<Message[]>;
  /** Outbound messages stuck in "queued" since before `before` (the sender crashed). */
  listStaleQueued(before: Date): Promise<Message[]>;

  insertAttachment(input: Omit<Attachment, "id"> & { ticketId: string; uploadedBy?: string | null }): Promise<Attachment>;
  getAttachment(id: string): Promise<(Attachment & { ticketId: string | null; uploadedBy: string | null }) | null>;
  /** Attaches uploaded files to the message they were sent with. */
  linkAttachments(ids: string[], messageId: string): Promise<void>;

  insertEvent(input: Omit<TicketEvent, "id" | "createdAt"> & { createdAt?: Date }): Promise<void>;
  listEvents(ticketId: string): Promise<TicketEvent[]>;

  markRead(ticketId: string, readerId: string, at: Date): Promise<void>;
  /** When `readerId` last read each ticket. */
  getReadTimes(ticketIds: string[], readerId: string): Promise<Map<string, Date>>;

  /* Insights: see `insights.ts` for how each number is defined. Indexes are in `0005_insights.sql`. */

  /** One period's totals. Called once for the period and once for the one before it. */
  periodTotals(range: StatsRange): Promise<PeriodTotals>;
  /** What the period breaks down into: per day and channel, per agent, the top customers, and the tickets behind the numbers. */
  periodBreakdown(range: StatsRange & { previousFrom: Date }): Promise<PeriodBreakdown>;

  getChannelState(channelId: string): Promise<ChannelState | null>;
  setChannelState(channelId: string, state: ChannelState, error?: string | null): Promise<void>;
}

export type NewContact = {
  name: string | null;
  customerId: string | null;
  userId: string | null;
  locale: string | null;
  identities: Identity[];
};

export type NewTicket = Pick<
  Ticket,
  "channelId" | "subject" | "status" | "contactId" | "customerId" | "assigneeId" | "replyToken" | "providerThreadId"
> & { createdAt: Date };

export type TicketPatch = Partial<
  Pick<
    Ticket,
    | "subject"
    | "status"
    | "contactId"
    | "customerId"
    | "assigneeId"
    | "providerThreadId"
    | "waitingSince"
    | "lastMessageAt"
    | "lastInboundAt"
    | "lastOutboundAt"
    | "solvedAt"
    | "preview"
    | "previewKind"
    | "previewAuthorId"
  >
>;

export type NewMessage = Omit<Message, "id" | "attachments">;

export type MessagePatch = Partial<
  Pick<Message, "deliveryStatus" | "deliveryError" | "providerMessageId" | "rfcMessageId">
>;

export type TicketQuery = {
  status?: TicketStatus;
  /** A user id, or null for unassigned tickets. Omit for everyone's. */
  assigneeId?: string | null;
  customerId?: string;
  channelId?: string;
  /** Opened from (included) to (not included). */
  createdFrom?: Date;
  createdTo?: Date;
  /** The topic Copilot or an agent filed it under. Needs the AI tables. */
  topic?: string;
  /** The customer portal: only tickets this person started. */
  contactUserId?: string;
  search?: string;
  /** Customers whose name matched the search, resolved by the directory. */
  searchCustomerIds?: string[];
  /** "priority": most urgent first (from Copilot's insights; needs the AI tables), then longest waiting. */
  sort: "waiting" | "recent" | "solved" | "priority";
  limit: number;
  offset: number;
};

export type TicketCounts = Record<TicketStatus, number> & { unassigned: number; mine: number };

export type { DeliveryStatus };

import type { Identity, IdentityKind } from "./types";

/**
 * Normalizes an identity so the same person always maps to the same contact.
 * Emails are lower-cased and trimmed, nothing more: dots and +tags are left alone, because
 * jane.doe@ and janedoe@ are different people on most providers.
 */
export function normalizeIdentity(kind: IdentityKind, value: string): Identity {
  const trimmed = value.trim();
  if (kind === "email") return { kind, value: trimmed.toLowerCase() };
  if (kind === "phone" || kind === "whatsapp") {
    const raw = trimmed.replace(/^whatsapp:/i, "");
    // WhatsApp users who hide their number arrive with a business-scoped id ("US.1349…"): keep it as is.
    if (/[a-z]/i.test(raw)) return { kind, value: raw };
    const digits = raw.replace(/[^\d+]/g, "");
    return { kind, value: digits.startsWith("+") ? digits : digits ? `+${digits}` : trimmed };
  }
  return { kind, value: trimmed };
}

/** "Re: Re: Fwd: Payout" → "Payout", for comparing subjects across a thread. */
export function baseSubject(subject: string | null | undefined): string {
  let s = (subject ?? "").trim();
  const prefix = /^(re|fw|fwd|tr|aw|wg|sv|vs|rv|réf|ref|رد|إعادة توجيه)\s*(\[\d+\])?\s*:\s*/i;
  while (prefix.test(s)) s = s.replace(prefix, "").trim();
  return s.replace(/\s+/g, " ");
}

export function replySubject(subject: string | null | undefined): string {
  const base = (subject ?? "").trim();
  return /^re\s*:/i.test(base) ? base : `Re: ${base}`;
}

/** Returns the ticket token from a reply address like "support+t-abc123@in.acme.com". */
export function tokenFromAddress(address: string): string | null {
  const local = address.split("@")[0] ?? "";
  return /\+t-([a-z0-9]{10,40})$/i.exec(local)?.[1]?.toLowerCase() ?? null;
}

/** "support@in.acme.com" + token → "support+t-<token>@in.acme.com". */
export function addressWithToken(address: string, token: string): string {
  const [local, domain] = address.split("@");
  return `${local}+t-${token}@${domain}`;
}

export function displayName(name: string | null | undefined, address: string): string {
  return name?.trim() || address;
}

/**
 * Plain-text helpers that run anywhere (Workers, Node, the browser): no DOM.
 *
 * Patterns follow Discourse's email_reply_trimmer, talon and Zammad. Arabic patterns are
 * best-effort: add real samples to tests/fixtures when you see a reply that isn't trimmed.
 */

const BIDI_CONTROLS = /[‎‏‪-‮⁦-⁩]/g;

/** Lines where quoted history starts. Everything from the match down is dropped. */
const QUOTE_HEADERS: RegExp[] = [
  /^[\s>]*(?:On|At)\s.{1,300}?\b(?:wrote|writes|said)\s*:?\s*$/i,
  /^[\s>]*.{1,250}\s(?:wrote|schrieb|a écrit|escribió)\s*:\s*$/i,
  /^[\s>]*Le\s.{1,300}?\ba\s+écrit\s*:?\s*$/i,
  /^[\s>]*(?:في|بتاريخ|يوم)\s.{1,300}?(?:تمت\s+كتابة\s+ما\s+يلي\s+بواسطة|كتب|كتبت)\s.{0,250}:\s*$/,
  /^[\s>]*.{1,250}\s(?:كتب|كتبت)\s*:\s*$/,
  /^[\s>]*.{0,40}\d{4}.{1,80}<[^@<>\s]+@[^@<>\s]+\.[^@<>\s]+>:?\s*$/,
  /^[\s>*]*-{2,}\s*(?:Original Message|Forwarded message|Reply Message|Message d'origine|Message transféré|Ursprüngliche Nachricht|Mensaje original|الرسالة الأصلية|رسالة معاد توجيهها)\s*-{2,}/i,
  /^[\s>]*(?:Begin forwarded message|Début du message (?:réexpédié|transféré))\s*:/i,
];

/** An Outlook-style "From: / Sent: / To: / Subject:" block. */
const HEADER_LABEL =
  /^[\s>*]*(?:From|Sent|Date|To|Cc|Subject|De|Envoyé|À|A|Objet|Von|Gesendet|An|Betreff|من|المرسل|تم الإرسال|التاريخ|إلى|نسخة|الموضوع)\s*:\s*\S/i;

/** Mobile signatures: only these lines are removed. */
const SIGNATURE_LINES: RegExp[] = [
  /^\s*[(<]*Sent (?:from|via|with|by) .+/i,
  /^\s*Get Outlook for /i,
  /^\s*Envoyé (?:depuis|de) (?:mon|Yahoo Mail)/i,
  /^\s*Obtenir Outlook pour /i,
  /^\s*(?:أرسلت|تم الإرسال|مرسل(?:ة)?) من (?:جهاز )?(?:الـ)?(?:iPhone|آيفون|هاتف|Android)/i,
];

/**
 * What the person wrote this time: drops quoted history, the "-- " signature and mobile
 * signatures. Falls back to the full text when trimming would leave nothing.
 */
export function visibleReply(text: string): string {
  const lines = text.replace(/\r\n?/g, "\n").replace(BIDI_CONTROLS, "").replace(/[  ]/g, " ").split("\n");
  let end = lines.length;
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    if (QUOTE_HEADERS.some((re) => re.test(line)) || isHeaderBlock(lines, i) || /^-- ?$/.test(line)) {
      end = i;
      break;
    }
    // A run of "> " lines at the end is quoted history even without a header.
    if (/^\s*>/.test(line) && lines.slice(i).every((l) => /^\s*(>|$)/.test(l))) {
      end = i;
      break;
    }
  }
  // The rule Outlook draws above its "From:" block ("________") belongs to the quote.
  if (end < lines.length) {
    while (end > 0 && /^\s*(?:[_\-=–—]\s*){5,}$|^\s*$/.test(lines[end - 1]!)) end--;
  }
  const kept = lines
    .slice(0, end)
    .filter((line) => !SIGNATURE_LINES.some((re) => re.test(line)))
    .join("\n")
    .trim();
  return kept || text.trim();
}

/** Where mail clients put the quoted message in HTML; a signature after this belongs to the quote. */
const HTML_QUOTE_START = /<blockquote|<div[^>]+(?:gmail_quote|yahoo_quoted|divRplyFwdMsg|appendonsend|moz-cite-prefix|protonmail_quote)/i;

/** Elements mail clients wrap the sender's signature in. */
const HTML_SIGNATURE =
  /<(div|table|p|span)\b[^>]*(?:\bid\s*=\s*["']?(?:Signature|ms-outlook-mobile-signature)\b|\bclass\s*=\s*["'][^"']*\b(?:gmail_signature|moz-signature)\b)[^>]*>/i;

/**
 * The sender's signature as plain text, when their mail client marked it in the HTML (Outlook,
 * Gmail, Thunderbird). Use it with `withoutSignature` to show only what they wrote.
 */
export function signatureFromHtml(html: string | null | undefined): string | null {
  if (!html) return null;
  const quote = html.search(HTML_QUOTE_START);
  const own = quote === -1 ? html : html.slice(0, quote);
  const open = HTML_SIGNATURE.exec(own);
  if (!open) return null;
  const tag = open[1]!.toLowerCase();
  // Walk to the matching close tag so nested elements of the same kind stay inside.
  const tags = new RegExp(`<(/?)${tag}\\b[^>]*>`, "gi");
  tags.lastIndex = open.index + open[0].length;
  let depth = 1;
  let close = own.length;
  for (let m = tags.exec(own); m; m = tags.exec(own)) {
    depth += m[1] ? -1 : 1;
    if (depth === 0) {
      close = m.index;
      break;
    }
  }
  const text = htmlToText(own.slice(open.index + open[0].length, close))
    .split("\n")
    .map((l) => l.trim())
    .filter(Boolean)
    .join("\n");
  return text || null;
}

/** Removes `signature` from the end of `text`, comparing line by line and ignoring spacing. */
export function withoutSignature(text: string, signature: string | null | undefined): string {
  if (!signature) return text;
  const norm = (l: string) => l.replace(/\s+/g, " ").trim();
  const sig = signature.split("\n").map(norm).filter(Boolean);
  const lines = text.split("\n");
  // Indexes of non-empty lines, so blank lines between signature lines don't matter.
  const filled = lines.flatMap((l, i) => (norm(l) ? [i] : []));
  if (!sig.length || filled.length <= sig.length) return text;
  const tail = filled.slice(-sig.length);
  if (!tail.every((i, k) => norm(lines[i]!) === sig[k])) return text;
  return lines.slice(0, tail[0]).join("\n").trim();
}

/** The quoted or forwarded email inside a message: who wrote it, when, and what they wrote. */
export type QuotedMessage = {
  from: { address: string; name: string | null };
  /** When the quoted email was sent, if its header gave a date we could read. */
  sentAt: Date | null;
  /** What the quoted email said, without its own quoted history. */
  text: string;
  /** What the sender wrote above the quote. */
  before: string;
};

const FROM_LABEL = /^[\s>*]*(?:From|De|Von|Da|Van|من|المرسل)\s*\*?\s*:\s*\*?\s*(.+)$/i;
const DATE_LABEL = /^[\s>*]*(?:Sent|Date|Envoyé|Gesendet|Datum|Fecha|Enviado|Data|تم الإرسال|التاريخ)\s*\*?\s*:\s*\*?\s*(.+)$/i;
const WROTE = /^\s*(?:wrote|a écrit|escribió|schrieb|schreef|ha scritto)\s*:?\s*$/i;
/** Gmail, Apple Mail and Thunderbird: "On Mon, Nov 9, 2026 at 4:23 PM Emma <emma@acme.test> wrote:". */
const ATTRIBUTION =
  /^[\s>]*(?:On|Le|El|Am|Op|Il)\s(.+?\d{1,2}[:.h]\d{2}(?::\d{2})?(?:\s*[AP]\.?M\.?)?|.+?),?\s+([^,<>]*?)\s*<([^<>\s]+@[^<>\s]+)>\s*(?:wrote|a écrit|escribió|schrieb|schreef|ha scritto)\s*:?\s*$/i;
const FORWARD_SEPARATOR =
  /^[\s>*]*(?:-{2,}\s*(?:Original Message|Forwarded message|Message d'origine|Message transféré|Ursprüngliche Nachricht|Mensaje original|الرسالة الأصلية|رسالة معاد توجيهها)\s*-{2,}|(?:Begin forwarded message|Début du message (?:réexpédié|transféré))\s*:)/i;
const RULE = /^\s*(?:[_\-=–—]\s*){5,}$/;

/**
 * The email quoted below a reply or inside a forward, read from the header mail clients put
 * above it: Outlook's "From: / Sent:" block, Gmail's "On … wrote:", Apple Mail's "Begin
 * forwarded message:". Pass the HTML too, for messages whose plain text leaves the quote out.
 * Returns null when there's no quote, or its sender has no email address.
 */
export function quotedMessage(text: string | null | undefined, html?: string | null): QuotedMessage | null {
  return (text ? findQuoted(text) : null) ?? (html ? findQuoted(htmlToText(html, { keepQuotes: true })) : null);
}

function findQuoted(source: string): QuotedMessage | null {
  const lines = source.replace(/\r\n?/g, "\n").replace(BIDI_CONTROLS, "").replace(/[  ]/g, " ").split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]!;
    let from: QuotedMessage["from"] | null = null;
    let date: string | null = null;
    let bodyStart = -1;
    let quoted = false;

    if (FROM_LABEL.test(line) && isHeaderBlock(lines, i)) {
      from = parseAddressText(FROM_LABEL.exec(line)![1]!);
      // The block ends at a blank line or the first line that isn't a header (a wrapped To: list may continue).
      let j = i;
      const isLabel = (k: number) => k < lines.length && HEADER_LABEL.test(lines[k]!);
      while (j < lines.length && lines[j]!.trim() !== "" && (isLabel(j) || isLabel(j + 1))) {
        const d = DATE_LABEL.exec(lines[j]!);
        if (d) date = d[1]!;
        j++;
      }
      bodyStart = j;
    } else {
      // Gmail wraps a long attribution onto two lines.
      const wrapped = lines[i + 1] !== undefined && WROTE.test(lines[i + 1]!);
      const m = ATTRIBUTION.exec(wrapped ? `${line} ${lines[i + 1]}` : line);
      if (m) {
        from = { address: m[3]!.toLowerCase(), name: unquote(m[2]!) };
        date = m[1]!.replace(/\s+(?:at|à)\s+/i, " ");
        bodyStart = wrapped ? i + 2 : i + 1;
        quoted = true;
      }
    }
    if (bodyStart === -1) continue;
    if (!from) return null;

    let end = i;
    while (end > 0 && (RULE.test(lines[end - 1]!) || FORWARD_SEPARATOR.test(lines[end - 1]!) || !lines[end - 1]!.trim())) end--;
    let body = lines.slice(bodyStart);
    if (quoted || body.filter((l) => l.trim()).every((l) => /^\s*>/.test(l))) body = body.map((l) => l.replace(/^\s*> ?/, ""));
    const quotedText = body.join("\n").trim();
    if (!quotedText) return null;
    return { from, sentAt: parseMailDate(date), text: visibleReply(quotedText), before: lines.slice(0, end).join("\n").trim() };
  }
  return null;
}

const unquote = (s: string) => s.replace(/^["']|["']$/g, "").trim() || null;

/** "Emma Clarke <emma@acme.test>", "Emma [mailto:emma@acme.test]" or "emma@acme.test". */
function parseAddressText(value: string): QuotedMessage["from"] | null {
  const clean = value.replace(/\*/g, "").trim();
  const m = /^(.*?)\s*[<[](?:mailto:)?([^<>[\]\s]+@[^<>[\]\s]+)[>\]]\s*$/i.exec(clean);
  if (m) return { address: m[2]!.toLowerCase(), name: unquote(m[1]!) };
  if (/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/.test(clean)) return { address: clean.toLowerCase(), name: null };
  return null;
}

function parseMailDate(value: string | null): Date | null {
  if (!value) return null;
  const ms = Date.parse(value.trim());
  return Number.isFinite(ms) ? new Date(ms) : null;
}

function isHeaderBlock(lines: string[], i: number): boolean {
  if (!HEADER_LABEL.test(lines[i]!)) return false;
  const following = lines.slice(i + 1, i + 5).filter((l) => HEADER_LABEL.test(l));
  return following.length >= 2;
}

const ENTITIES: Record<string, string> = { amp: "&", lt: "<", gt: ">", quot: '"', apos: "'", nbsp: " " };

/** Readable text from HTML email, without a DOM. Quotes become "> " lines so trimming still works. */
export function htmlToText(html: string, options: { keepQuotes?: boolean } = {}): string {
  let s = html
    .replace(/<!--[\s\S]*?-->/g, "")
    .replace(/<(head|style|script|title)[^>]*>[\s\S]*?<\/\1>/gi, "")
    // Known quote containers: everything inside becomes quoted.
    .replace(/<blockquote[^>]*>([\s\S]*?)<\/blockquote>/gi, (_, inner: string) =>
      `\n${htmlToText(inner).split("\n").map((l) => `> ${l}`).join("\n")}\n`
    );
  if (!options.keepQuotes) {
    s = s.replace(/<div[^>]+(?:gmail_quote|yahoo_quoted|divRplyFwdMsg|appendonsend|moz-cite-prefix|protonmail_quote)[\s\S]*$/i, "\n> \n");
  }
  s = s
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/(p|div|h[1-6]|li|tr|table|ul|ol|section|article)>/gi, "\n")
    .replace(/<li[^>]*>/gi, "• ")
    .replace(/<a[^>]+href="([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, (_, href: string, label: string) => {
      const text = label.replace(/<[^>]+>/g, "").trim();
      return text && text !== href && /^https?:/i.test(href) ? `${text} (${href})` : text || href;
    })
    .replace(/<[^>]+>/g, "");
  s = s.replace(/&(#x?[0-9a-f]+|[a-z]+);/gi, (m, code: string) => {
    if (code[0] === "#") {
      const n = code[1]?.toLowerCase() === "x" ? parseInt(code.slice(2), 16) : parseInt(code.slice(1), 10);
      return Number.isFinite(n) ? String.fromCodePoint(n) : m;
    }
    return ENTITIES[code.toLowerCase()] ?? m;
  });
  return s
    .split("\n")
    .map((l) => l.replace(/[ \t]+/g, " ").trimEnd())
    .join("\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

export function snippet(text: string, length = 160): string {
  const flat = text.replace(/\s+/g, " ").trim();
  return flat.length > length ? `${flat.slice(0, length - 1).trimEnd()}…` : flat;
}

/**
 * Why a message was sent by a machine (out-of-office, bounce, mailing list), or null when a
 * person wrote it. Automated mail never reopens a ticket, notifies anyone or gets an acknowledgement.
 */
export function automatedReason(headers: Record<string, string> | undefined, from: string): string | null {
  const h = (name: string) => headers?.[name];
  const v = (name: string) => (h(name) ?? "").trim().toLowerCase();
  const autoSubmitted = v("auto-submitted");
  if (autoSubmitted && !/^no\b/.test(autoSubmitted)) return "auto-submitted";
  if (["x-autoreply", "x-autorespond", "x-autoresponder", "x-autoreply-from", "x-mail-autoreply"].some((n) => v(n)))
    return "auto-reply";
  if (/\b(bulk|list|junk|auto_reply)\b/.test(v("precedence") || v("x-precedence"))) return "precedence";
  if (["list-id", "list-unsubscribe", "list-post"].some((n) => h(n) !== undefined)) return "mailing-list";
  if (/\ball\b|\boof\b|autoreply/.test(v("x-auto-response-suppress"))) return "auto-reply";
  if (v("return-path") === "<>") return "null-return-path";
  if (h("x-failed-recipients") !== undefined) return "bounce";
  if (/multipart\/report/.test(v("content-type"))) return "report";
  if (/^(mailer-daemon|postmaster|bounces?|listserv|majordomo)@|^owner-|-request@/i.test(from)) return "system-sender";
  return null;
}

/** Plain text to the minimal HTML we send: escaped, paragraphs, links, direction per paragraph. */
export function textToHtml(text: string): string {
  const escape = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
  const paragraphs = text
    .replace(/\r\n?/g, "\n")
    .trim()
    .split(/\n{2,}/)
    .map((p) =>
      `<p dir="auto" style="margin:0 0 1em">${escape(p)
        .replace(/(https?:\/\/[^\s<]+)/g, '<a href="$1">$1</a>')
        .replace(/\n/g, "<br>")}</p>`
    );
  return `<div dir="auto" style="font-family:system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;font-size:14px;line-height:1.6;color:#111">${paragraphs.join("")}</div>`;
}

/**
 * True when the receiving server recorded that the sender failed authentication: DMARC failed,
 * or neither SPF nor DKIM passed. Such mail still becomes a ticket, but it isn't linked to the
 * customer it claims to come from and gets no automatic reply.
 */
export function senderFailedAuthentication(headers: Record<string, string> | undefined): boolean {
  const results = headers?.["authentication-results"]?.toLowerCase();
  if (!results) return false;
  if (/\bdmarc=fail\b/.test(results)) return true;
  const spfFailed = /\bspf=(fail|softfail)\b/.test(results);
  const dkimFailed = /\bdkim=(fail|none)\b/.test(results) && !/\bdkim=pass\b/.test(results);
  return spfFailed && dkimFailed;
}

